mapper.update:
UPDATE b_daily_train_seat SET sell = CASE id
WHEN #{s.id} THEN #{s.sell}
END, updated_at = CURRENT_TIMESTAMP WHERE id IN #{s.id}

mapper.select:
SELECT id, ride_date, train_code, carriage_no, row_no, col_no, seat_type, sell,
       created_at, updated_at
FROM b_daily_train_seat
WHERE ride_date = #{rideDate}
  AND train_code = #{trainCode}
  AND seat_type = #{seatType}
  AND SUBSTRING(sell, #{fromIdx} + 1, #{toIdx} - #{fromIdx}) NOT LIKE '%1%'
ORDER BY carriage_no, row_no, col_no
